const test = require('node:test');
const assert = require('node:assert/strict');
const { resolveLink } = require('../resolve-link.cjs');
test('document versus directory base', () => {
  assert.equal(resolveLink('https://guide.invalid/plans/day.html', 'map.svg'), 'https://guide.invalid/plans/map.svg');
  assert.equal(resolveLink('https://guide.invalid/plans/', 'map.svg'), 'https://guide.invalid/plans/map.svg');
  assert.equal(resolveLink('https://guide.invalid/plans/day.html', '../map.svg'), 'https://guide.invalid/map.svg');
});
test('other URL reference forms', () => {
  const base = 'https://guide.invalid/plans/day.html';
  assert.equal(resolveLink(base, '?print=1'), base + '?print=1');
  assert.equal(resolveLink(base, '#north'), base + '#north');
  assert.equal(resolveLink(base, ''), base);
  assert.equal(resolveLink(base, '/tiles/a'), 'https://guide.invalid/tiles/a');
  assert.equal(resolveLink(base, 'https://media.invalid/p.png'), 'https://media.invalid/p.png');
});

